import {clone,uid} from './model.js';
import {captureProduct,assertProductSource} from './product-workflow.js';
import {validateSceneRecipe} from './scene-recipe.js';
import {assertImageDimensions} from './capacity.js';
export function captureScene(doc,layer){if(doc.selection)throw Error('Bỏ vùng chọn tài liệu trước khi mở Preset & Mùa.');if(layer?.locked&&layer?.sceneRecipe)throw Error('Mở khóa layer trước khi chỉnh lại.');return captureProduct(doc,layer);}
export function applyScene(doc,snapshot,output,recipe,assets){const current=assertProductSource(doc,snapshot);validateSceneRecipe(recipe,s=>{if(typeof s!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(s)&&s!=='assets/wave.jpg')throw Error('Invalid scene source.');});if(output.width!==recipe.width||output.height!==recipe.height)throw Error('Scene output dimensions mismatch.');if(!current.sceneRecipe&&doc.layers.length>=150)throw Error('Đã đạt giới hạn150 layer.');const source=output.toDataURL('image/png');if(!source.startsWith('data:image/png'))throw Error('Trình duyệt chưa mã hóa được ảnh gốc. Nguồn vẫn giữ nguyên.');const next={...clone(current),source,sceneRecipe:clone(recipe)};if(recipe.bakedMask)next.mask=null;for(const k of ['photoRecipe','removalRecipe','productRecipe','cutoutRecipe','paperRecipe','colorRecipe','landscapeRecipe','artRecipe','generation','assistance'])delete next[k];if(!current.sceneRecipe){next.id=uid();next.visible=true;next.locked=false;next.name=current.name.slice(0,120)+' · Preset & Mùa';}assets.set(source,output);if(current.sceneRecipe)Object.assign(current,next);else{doc.layers.splice(doc.layers.indexOf(current)+1,0,next);current.visible=false;}doc.activeId=next.id;doc.selectedIds=[next.id];return next;}
